export function buildPlayersList(
  response: Pick<LavalinkNodesResponse, "nodes">,
  nowMs: number = Date.now(),
  gateway: GatewayPlayersView = EMPTY_GATEWAY_VIEW,
): PlayersList {
  const { currentTracks, mirror247, queueSizes } = gateway;
  const rows: PlayerRow[] = [];
  let playing = 0;
  let paused = 0;
  let stopped = 0;
  let persistent = 0;
  let voiceless = 0;
  let nodesUnreported = 0;
  let rowsUnverified247 = 0;
  const bots = new Set<string>();

  for (const node of response.nodes) {
    if (node.playerList === null) {
      nodesUnreported++;
      continue;
    }
    for (const p of node.playerList) {
      // Misma precedencia que el `countPlayerStates` del gateway: pausado gana
      // sobre sonando, y sonando sobre detenido. Copiarla es lo que impide que
      // los `StatBadge` se muevan de sitio al cambiar de fuente de datos.
      if (p.paused) paused++;
      else if (p.playing) playing++;
      else stopped++;
      if (p.persistent) persistent++;
      // Cruzado con los tres de arriba, no sumado: este player ya está contado
      // dentro de `playing`, que es precisamente por lo que hacía falta.
      if (isVoicelessPlaying(p)) voiceless++;
      bots.add(p.botUserId);

      // `?? null` y no `?? false`: `Map.get` devuelve `undefined` cuando el
      // gateway no habló de este player, y eso es «no lo sé». Convertirlo en
      // `false` haría que cada fila 24/7 de un gateway caído se pintara como
      // deriva — inventar averías en lote, que es lo contrario de delatarlas.
      const gatewayKey = currentTrackKey(p.botUserId, p.guildId);
      const mirror = mirror247.get(gatewayKey) ?? null;
      if (mirror === null) rowsUnverified247++;

      rows.push({
        guildId: p.guildId,
        botId: p.botUserId,
        sessionId: p.sessionId,
        nodeName: node.name,
        voiceId: p.voiceChannelId,
        paused: p.paused,
        playing: p.playing,
        loop: p.repeatMode === "off" ? "none" : p.repeatMode,
        volume: p.volume,
        position: p.position,
        connected: p.connected,
        // Mismo `Math.max(0, nowMs - …)` que `idleForMs` y por el mismo motivo:
        // absorbe el desfase de reloj entre el nodo y esta máquina, que si no
        // pintaría un «sin voz · hace -3 s». Y va en el servidor por la razón que
        // encabeza esta función: el reloj del cliente no es de fiar.
        voiceDownForMs:
          !p.connected && typeof p.disconnectedSinceMs === "number"
            ? Math.max(0, nowMs - p.disconnectedSinceMs)
            : null,
        // Sin normalizar: traducir el `-1` a «—» es cosa de la celda, y un `0`
        // colándose aquí sería indistinguible de una medida real.
        ping: p.ping,
        // El nodo no trae carátula NUNCA, y de un fichero interno tampoco trae
        // el nombre (ver «Injerto desde la cola de Redis»): se le injertan los
        // de la cola cuando la identidad cuadra. El `fileId` se resuelve aquí,
        // una sola vez, y lo usan las dos cosas —la guarda del injerto y el
        // botón de copiar de la celda—.
        track: graftFromQueue(
          p.track
            ? {
                title: p.track.title,
                author: p.track.author,
                length: p.track.length,
                isStream: p.track.isStream,
                uri: p.track.uri,
                artworkUrl: p.track.artworkUrl,
                sourceName: p.track.sourceName,
