```
function buildNodeSummary(
	node: DeclaredNode,
	disabled: Set<string>,
	stats: LavalinkNodeStats | null,
	players: NodePlayerRow[] | null,
	commit: string | null,
	probedAt: string
): NodeSummary {
	return {
		name: node.id,
		host: node.host,
		port: node.port,
		region: node.region ?? null,
		group: node.group ?? null,
		// `enabled` refleja el estado operador (botón del panel), que solo
		// vive en Redis porque el nodo no puede conocerlo. `connected` refleja
		// el estado runtime: el nodo contestó al probe hace un instante.
		enabled: !disabled.has(node.id),
		connected: stats !== null,
		// Cuatro universos distintos: `players` cuenta todas las sesiones del
		// nodo (es el que importa para evacuar), `playingPlayers` las que tienen
		// audio sonando, `pausedPlayers` las pausadas, y `disconnectedPlayers`
		// las que el nodo tiene en memoria pero cuya voz se cayó.
		players: stats?.players ?? null,
		playingPlayers: stats?.playingPlayers ?? null,
		pausedPlayers: stats?.pausedPlayers ?? null,
		disconnectedPlayers: stats?.disconnectedPlayers ?? null,
		persistentPlayers: stats?.persistentPlayers ?? null,
		persistentPlayingPlayers: stats?.persistentPlayingPlayers ?? null,
		persistentPausedPlayers: stats?.persistentPausedPlayers ?? null,
		stats,
		playerList: players,
		commit,
		probedAt
	};
}
```

