pub async fn patch_player(
    State(state): State<AppState>,
    Path((session_id, guild_id)): Path<(String, String)>,
    Json(body): Json<UpdatePlayerRequest>,
) -> Result<Json<PlayerRest>, ApiError> {
    tracing::info!(
        session_id = %session_id,
        guild_id = %guild_id,
        has_voice = body.voice.is_some(),
        has_track = body.track.is_some(),
        // Nested v4 fields — distinct from the legacy top-level ones below.
        // `track_encoded_null = Some(true)` is the `stopTrack` idiom; without
        // this, "field absent" and "explicit null" were indistinguishable
        // from the outside, which is exactly what hid the double-`Option`
        // deserialize bug (null silently collapsed to absent) that broke
        // skip's `stopTrack -> TrackEndEvent(Stopped) -> next _play()` chain.
        track_encoded_null = ?body.track.as_ref().and_then(|t| t.encoded.as_ref()).map(Option::is_none),
        track_has_identifier = body.track.as_ref().is_some_and(|t| t.identifier.is_some()),
        has_encoded_track = body.encoded_track.is_some(),
        has_identifier = body.identifier.is_some(),
        position = ?body.position,
        paused = ?body.paused,
        volume = ?body.volume,
        "PATCH /players received"
    );
    let session = require_session(&state, &session_id).await?;
    let key = PlayerKey {
        session_id: session_id.clone(),
        guild_id: guild_id.clone(),
    };

    // Serialize concurrent PATCHes on the same guild. Without this lock, a
    // music-module skip (`stopTrack` → immediate `_play()` from the queue
    // advance handler) races the two REST calls: both read the same base
    // `PlayerState`, both mutate it, and the second `save_player` wipes the
    // first's changes. Symptoms include the "same song replays after skip"
    // bug and the stale `connected` flag issue.
    let lock = state.store.player_lock(&key).await;
    let _guard = lock.lock().await;

    let mut player = match state.store.get_player(&key).await {
        Some(p) => p,
        None => PlayerState::new(key.clone(), session.bot_user_id.clone(), now_ms()),
    };

    let identity = PlayerIdentity {
        key: key.clone(),
        bot_user_id: session.bot_user_id.clone(),
    };

    // voice update always first — songbird can't play into a disconnected driver.
    if let Some(voice) = body.voice {
        player.voice = Some(voice.clone());
        match state.audio.update_voice(identity.clone(), voice).await {
            Ok(_) => player.connected = true,
            Err(e) => {
                tracing::warn!(error = %e, "audio.update_voice failed");
                player.connected = false;
            }
        }
    }

    // Resolve the incoming track update (if any) BEFORE touching pause / volume /
