        // `track_encoded_null = Some(true)` is the `stopTrack` idiom; without
        // this, "field absent" and "explicit null" were indistinguishable
        // from the outside, which is exactly what hid the double-`Option`
        // deserialize bug (null silently collapsed to absent) that broke
        // skip's `stopTrack -> TrackEndEvent(Stopped) -> next _play()` chain.
        track_encoded_null = ?body.track.as_ref().and_then(|t| t.encoded.as_ref()).map(Option::is_none),
        track_has_identifier = body.track.as_ref().is_some_and(|t| t.identifier.is_some()),
        has_encoded_track = body.encoded_track.is_some(),
        has_identifier = body.identifier.is_some(),
        position = ?body.position,
        paused = ?body.paused,
        volume = ?body.volume,
