            self.push(Call::Play {
                title: track.info.title,
                position: position_ms,
                filter_vol: filters.volume,
            });
            Ok(())
        }
        async fn stop(&self, _who: PlayerIdentity) -> Result<(), AudioError> {
            self.push(Call::Stop);
            Ok(())
        }
        async fn pause(&self, _who: PlayerIdentity, paused: bool) -> Result<(), AudioError> {
            self.push(Call::Pause(paused));
            Ok(())
        }
        async fn seek(&self, _who: PlayerIdentity, position_ms: i64) -> Result<(), AudioError> {
            self.push(Call::Seek(position_ms));
