        }
        async fn set_volume(&self, _who: PlayerIdentity, volume: u16) -> Result<(), AudioError> {
            self.push(Call::SetVolume(volume));
            Ok(())
        }
        async fn apply_filters(
            &self,
            _who: PlayerIdentity,
