use serde::{Deserialize, Serialize};

/// Deserialize a JSON field that must distinguish "absent" from "explicit
/// null" — e.g. Lavalink v4's `track.encoded: null` (stop the track) vs the
/// field simply not being present in the PATCH body (leave it alone).
///
/// Plain `Option<Option<T>>` collapses both cases to the outer `None`
/// because `Option<T>`'s `Deserialize` impl treats a JSON `null` as its own
/// `None` without ever invoking this function — `#[serde(default)]` then
/// supplies the same `None` for a field that was never sent. Routing
/// present-but-null fields through this deserializer (invoked only when the
/// key exists) fixes that: absent -> `None` (via `default`), `null` ->
/// `Some(None)`, value -> `Some(Some(value))`.
fn double_option<'de, T, D>(deserializer: D) -> Result<Option<Option<T>>, D::Error>
where
    T: Deserialize<'de>,
    D: serde::Deserializer<'de>,
{
    Ok(Some(Option::deserialize(deserializer)?))
}

