#[cfg(test)]
mod double_option_tests {
    use super::{UpdatePlayerRequest, UpdatePlayerTrack};

    // Regression test for the "skip doesn't advance to next song" bug:
    // a `stopTrack` PATCH sends `track.encoded: null` (or legacy
    // `encodedTrack: null`) to explicitly stop playback. Before
    // `double_option`, `Option<Option<String>>` couldn't tell that apart
    // from the field being absent, so the stop silently no-op'd, no
    // TrackEndEvent(Stopped) was emitted, and the queue-advance handler
    // listening for it never sent the follow-up `_play()` for the next
    // track.
    #[test]
    fn nested_track_encoded_null_is_distinguishable_from_absent() {
        let explicit_null: UpdatePlayerTrack =
            serde_json::from_str(r#"{"encoded": null}"#).unwrap();
        assert_eq!(explicit_null.encoded, Some(None), "explicit null must stop the track");

        let absent: UpdatePlayerTrack = serde_json::from_str(r#"{}"#).unwrap();
        assert_eq!(absent.encoded, None, "absent field must leave the track untouched");

        let present: UpdatePlayerTrack =
            serde_json::from_str(r#"{"encoded": "abc"}"#).unwrap();
        assert_eq!(present.encoded, Some(Some("abc".to_string())));
    }

    #[test]
    fn legacy_top_level_encoded_track_null_is_distinguishable_from_absent() {
        let explicit_null: UpdatePlayerRequest =
            serde_json::from_str(r#"{"encodedTrack": null}"#).unwrap();
        assert_eq!(explicit_null.encoded_track, Some(None));

        let absent: UpdatePlayerRequest = serde_json::from_str(r#"{}"#).unwrap();
        assert_eq!(absent.encoded_track, None);
    }

    #[test]
    fn end_time_null_clears_rather_than_no_ops() {
        let explicit_null: UpdatePlayerRequest =
            serde_json::from_str(r#"{"endTime": null}"#).unwrap();
        assert_eq!(explicit_null.end_time, Some(None));

        let absent: UpdatePlayerRequest = serde_json::from_str(r#"{}"#).unwrap();
        assert_eq!(absent.end_time, None);
    }

    #[test]
    fn filters_top_level_null_clears_all() {
        let req: UpdatePlayerRequest =
            serde_json::from_str(r#"{"filters": null}"#).unwrap();
        assert!(matches!(req.filters, Some(None)));
    }

    #[test]
    fn filters_field_null_vs_absent_vs_value() {
        let cleared: UpdatePlayerRequest =
            serde_json::from_str(r#"{"filters": {"equalizer": null}}"#).unwrap();
        let patch = cleared.filters.unwrap().unwrap();
        assert!(matches!(patch.equalizer, Some(None)),
            "equalizer:null must clear the filter");
        assert!(patch.karaoke.is_none(), "absent karaoke must stay untouched");

        let set: UpdatePlayerRequest =
            serde_json::from_str(r#"{"filters": {"equalizer": [{"band":0,"gain":0.5}]}}"#).unwrap();
        let patch = set.filters.unwrap().unwrap();
        assert!(matches!(patch.equalizer, Some(Some(ref v)) if v.len() == 1));
    }
}

