use async_trait::async_trait;
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::Mutex;

use super::{PlayerKey, PlayerState, Session, StateStore};

#[derive(Default, Clone)]
pub struct MemoryStateStore {
    inner: Arc<Inner>,
}

#[derive(Default)]
struct Inner {
    sessions: DashMap<String, Session>,
    players: DashMap<PlayerKey, PlayerState>,
    locks: DashMap<PlayerKey, Arc<Mutex<()>>>,
}

impl MemoryStateStore {
    pub fn new() -> Self {
        Self::default()
    }
}

#[async_trait]
impl StateStore for MemoryStateStore {
    async fn save_session(&self, session: Session) {
        self.inner.sessions.insert(session.session_id.clone(), session);
    }

    async fn get_session(&self, session_id: &str) -> Option<Session> {
        self.inner.sessions.get(session_id).map(|s| s.clone())
    }

    async fn delete_session(&self, session_id: &str) {
        self.inner.sessions.remove(session_id);
    }

    async fn list_sessions(&self) -> Vec<Session> {
        self.inner.sessions.iter().map(|e| e.value().clone()).collect()
    }

    async fn save_player(&self, player: PlayerState) {
        self.inner.players.insert(player.key.clone(), player);
    }

    async fn get_player(&self, key: &PlayerKey) -> Option<PlayerState> {
        self.inner.players.get(key).map(|p| p.clone())
    }

    async fn list_players(&self, session_id: &str) -> Vec<PlayerState> {
        self.inner
            .players
            .iter()
            .filter(|e| e.key().session_id == session_id)
            .map(|e| e.value().clone())
            .collect()
    }

    async fn delete_player(&self, key: &PlayerKey) {
        self.inner.players.remove(key);
    }

    async fn delete_players_for_session(&self, session_id: &str) {
        self.inner.players.retain(|k, _| k.session_id != session_id);
    }

    async fn total_players(&self) -> u32 {
        self.inner.players.len() as u32
    }

    async fn playing_players(&self) -> u32 {
        self.inner
            .players
            .iter()
            .filter(|e| e.value().track.is_some() && !e.value().paused)
            .count() as u32
    }

    async fn player_lock(&self, key: &PlayerKey) -> Arc<Mutex<()>> {
        self.inner
            .locks
            .entry(key.clone())
            .or_insert_with(|| Arc::new(Mutex::new(())))
            .clone()
    }
}

use axum::{
    extract::{
        ws::{Message, WebSocket, WebSocketUpgrade},
        State,
    },
    http::{HeaderMap, StatusCode},
    response::IntoResponse,
};
use futures::{SinkExt, StreamExt};
use std::time::Duration;
use tokio::time::interval;

use crate::app_state::AppState;
use crate::protocol::{StatsPayload, WsMessageOut};
use crate::state::Session;
use crate::util::{now_ms, random_session_id};

const STATS_INTERVAL: Duration = Duration::from_secs(60);
const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(30);

/// Monotonic source for per-connection epochs (see `AppState::conn_epoch`).
static CONN_EPOCH: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

pub async fn ws_handler(
    State(state): State<AppState>,
    headers: HeaderMap,
    ws: WebSocketUpgrade,
) -> Result<axum::response::Response, StatusCode> {
    let auth = headers
        .get("Authorization")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    if auth != state.config.lavalink.password {
        return Err(StatusCode::UNAUTHORIZED);
    }
    let user_id = headers
        .get("User-Id")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string())
        .ok_or(StatusCode::BAD_REQUEST)?;
    let client_name = headers
        .get("Client-Name")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("unknown")
        .to_string();
    let resume_session_id = headers
        .get("Session-Id")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string());

    Ok(ws.on_upgrade(move |socket| async move {
        handle_socket(socket, state, user_id, client_name, resume_session_id).await;
    })
    .into_response())
}

async fn handle_socket(
    socket: WebSocket,
    state: AppState,
    user_id: String,
    client_name: String,
    resume_session_id: Option<String>,
) {
    // Resume protocol: if the client sends `Session-Id` for a session with
    // `resume_enabled=true` and there's a pending-cleanup timer, cancel the
    // timer and reuse everything (session row + players + audio drivers).
    // Otherwise fall through to a fresh session.
    let (session_id, session, resumed) = 'setup: {
        if let Some(prev) = resume_session_id.as_deref() {
            if let Some(existing) = state.store.get_session(prev).await {
                if existing.resume_enabled {
                    if let Some((_, task)) = state.pending_resume.remove(prev) {
                        task.abort();
                        tracing::info!(
                            session_id = %prev,
                            "ws resume: cancelling pending cleanup, reusing session"
                        );
                    } else {
                        tracing::info!(
                            session_id = %prev,
                            "ws resume: no cleanup pending, reusing session"
                        );
                    }
                    let mut refreshed = existing;
                    refreshed.last_seen_at_ms = now_ms();
                    refreshed.resumed = true;
                    state.store.save_session(refreshed.clone()).await;
                    break 'setup (prev.to_string(), refreshed, true);
                }
                tracing::warn!(
                    session_id = %prev,
                    "ws resume: session exists but resume disabled, issuing new session"
                );
            } else {
                tracing::warn!(
                    session_id = %prev,
                    "ws resume: unknown session id, issuing new session"
                );
            }
        }
        let sid = random_session_id();
        let now = now_ms();
        let s = Session {
            session_id: sid.clone(),
            bot_user_id: user_id.clone(),
            client_name: client_name.clone(),
            resumed: false,
            created_at_ms: now,
            last_seen_at_ms: now,
            resume_enabled: false,
            timeout_secs: 60,
        };
        state.store.save_session(s.clone()).await;
        (sid, s, false)
    };

    // Claim a fresh epoch for this connection. Any grace-period cleanup task
    // spawned by an earlier connection on this session will now see a newer
    // epoch and abort itself instead of destroying our players.
    let my_epoch = CONN_EPOCH.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    state.conn_epoch.insert(session_id.clone(), my_epoch);

    tracing::info!(%session_id, user_id = %session.bot_user_id, %client_name, resumed, epoch = my_epoch, "ws session opened");

    let (mut sink, mut stream) = socket.split();

    if let Ok(ready) = serde_json::to_string(&WsMessageOut::Ready {
        resumed,
        session_id: session_id.clone(),
    }) {
        let _ = sink.send(Message::Text(ready.into())).await;
    }

    let mut events = state.events.subscribe();
    let mut stats_ticker = interval(STATS_INTERVAL);
    let mut heartbeat = interval(HEARTBEAT_INTERVAL);
    stats_ticker.tick().await;
    heartbeat.tick().await;

    let session_id_for_loop = session_id.clone();
    let state_clone = state.clone();

    loop {
        tokio::select! {
            ev = events.recv() => {
                match ev {
                    Ok(ev) if ev.session_id == session_id_for_loop => {
                        if let Ok(txt) = serde_json::to_string(&ev.message) {
                            if sink.send(Message::Text(txt.into())).await.is_err() {
                                break;
                            }
                        }
                    }
                    Ok(_) => {} // event for other session
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                        tracing::warn!(session = %session_id_for_loop, lagged = n, "ws event channel lagged");
                    }
                    Err(_) => break,
                }
            }
            _ = stats_ticker.tick() => {
                let stats = build_stats(&state_clone).await;
                if let Ok(txt) = serde_json::to_string(&WsMessageOut::Stats(stats)) {
                    if sink.send(Message::Text(txt.into())).await.is_err() {
                        break;
                    }
                }
            }
            _ = heartbeat.tick() => {
                if sink.send(Message::Ping(Vec::new().into())).await.is_err() {
                    break;
                }
            }
            msg = stream.next() => {
                match msg {
                    Some(Ok(Message::Close(_))) | None => break,
                    Some(Err(e)) => {
                        tracing::warn!(error = %e, "ws recv error");
                        break;
                    }
                    Some(Ok(_)) => {} // pong, ping, text, binary -> ignored
                }
            }
        }
    }

    // Re-read the session so a mid-connection `PATCH /sessions/{id}` that
    // enables resume takes effect on the very close that follows.
    let current_session = state
        .store
        .get_session(&session_id_for_loop)
        .await
        .unwrap_or(session);

    if current_session.resume_enabled && current_session.timeout_secs > 0 {
        let timeout = Duration::from_secs(current_session.timeout_secs);
        tracing::info!(
            session_id = %session_id_for_loop,
            grace_secs = current_session.timeout_secs,
            "ws session closed — holding players for resume grace period"
        );
        let state_for_task = state.clone();
        let sid_for_task = session_id_for_loop.clone();
        let epoch_for_task = my_epoch;
        let task = tokio::spawn(async move {
            tokio::time::sleep(timeout).await;
            // Reattach guard: if a newer connection claimed this session while
            // we slept, its epoch overwrote ours — abort without touching the
            // resumed players. Covers the race where the reconnect's
            // `pending_resume.remove` ran before this timer was even inserted.
            let still_ours = state_for_task
                .conn_epoch
                .get(&sid_for_task)
                .map(|e| *e == epoch_for_task)
                .unwrap_or(false);
            if !still_ours {
                tracing::info!(
                    session_id = %sid_for_task,
                    "ws resume grace period expired but session reattached — keeping players"
                );
                state_for_task.pending_resume.remove(&sid_for_task);
                return;
            }
            tracing::info!(
                session_id = %sid_for_task,
                "ws resume grace period expired — destroying players"
            );
            for player in state_for_task.store.list_players(&sid_for_task).await {
                let identity = crate::audio::PlayerIdentity {
                    key: player.key.clone(),
                    bot_user_id: player.bot_user_id.clone(),
                };
                let _ = state_for_task.audio.destroy(identity).await;
            }
            state_for_task
                .store
                .delete_players_for_session(&sid_for_task)
                .await;
            state_for_task.store.delete_session(&sid_for_task).await;
            state_for_task.pending_resume.remove(&sid_for_task);
            // Only drop the epoch if it's still ours — a reconnect that landed
            // in the tiny window after the guard check must keep its own entry.
            state_for_task
                .conn_epoch
                .remove_if(&sid_for_task, |_, e| *e == epoch_for_task);
        });
        state.pending_resume.insert(session_id_for_loop, task);
    } else {
        tracing::info!(%session_id_for_loop, "ws session closing — destroying players");
        for player in state.store.list_players(&session_id_for_loop).await {
            let identity = crate::audio::PlayerIdentity {
                key: player.key.clone(),
                bot_user_id: player.bot_user_id.clone(),
            };
            let _ = state.audio.destroy(identity).await;
        }
        state
            .store
            .delete_players_for_session(&session_id_for_loop)
            .await;
        state.store.delete_session(&session_id_for_loop).await;
        state
            .conn_epoch
            .remove_if(&session_id_for_loop, |_, e| *e == my_epoch);
    }
}

pub async fn build_stats(state: &AppState) -> StatsPayload {
    StatsPayload {
        players: state.store.total_players().await,
        playing_players: state.store.playing_players().await,
        uptime: state.started_at.elapsed().as_millis() as u64,
        memory: Default::default(),
        cpu: Default::default(),
        frame_stats: None,
    }
}

